  {
    "name": "calculator",
    "description": "Evaluate an arithmetic expression and return the exact numeric result",
    "parameters": {
      "type": "object",
      "properties": {
        "expression": {
          "type": "string",
          "description": "The math expression, e.g., '15 * 4 + 10'"
        }
      },
      "required": [
        "expression"
      ]
    }
  },
  {
    "name": "read_file",
    "description": "Read the text content of a file within the workspace",
    "parameters": {
      "type": "object",
      "properties": {
        "path": {
          "type": "string",
          "description": "Relative file path"
        }
      },
      "required": [
        "path"
      ]
    }
  },
  {
    "name": "write_file",
    "description": "Write text content to a file, automatically creating parent directories",
    "parameters": {
      "type": "object",
      "properties": {
        "path": {
          "type": "string",
          "description": "Relative file path"
        },
        "content": {
          "type": "string",
          "description": "Text content to write"
        }
      },
      "required": [
        "path",
        "content"
      ]
    }
  },
  {
    "name": "list_dir",
    "description": "List all files and folders inside a given workspace directory",
    "parameters": {
      "type": "object",
      "properties": {
        "path": {
          "type": "string",
          "description": "Relative directory path, e.g., '.'"
        }
      },
      "required": [
        "path"
      ]
    }
  }
]
</tools>
